(()=>{
'use strict';
if(window.__gtavModsMultiDownloadV1)return;window.__gtavModsMultiDownloadV1=true;
const API='/api/mods';
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="lib-icon" aria-hidden="true"><use href="assets/icons.svg#${name}"></use></svg>`;
function waitForLibrary(){return new Promise(resolve=>{if(document.querySelector('.library-feed .library-card'))return resolve();const o=new MutationObserver(()=>{if(document.querySelector('.library-feed .library-card')){o.disconnect();resolve()}});o.observe(document.documentElement,{childList:true,subtree:true});setTimeout(()=>{o.disconnect();resolve()},8000)})}
async function getMods(){try{const r=await fetch(API,{cache:'no-store'});if(!r.ok)throw new Error();const d=await r.json();return Array.isArray(d.mods)?d.mods:[]}catch{return[]}}
function optionsFor(item){const source=Array.isArray(item?.downloadOptions)?item.downloadOptions:[];const result=[],seen=new Set();for(const entry of source){const url=String(entry?.url||entry?.downloadUrl||'').trim();if(!url||seen.has(url))continue;seen.add(url);result.push({label:String(entry?.label||entry?.title||`File ${result.length+1}`).trim()||`File ${result.length+1}`,url})}if(!result.length&&item?.downloadUrl)result.push({label:'Main file',url:item.downloadUrl});return result}
function enhance(card,item){if(!card||card.dataset.multiDownloadReady==='1')return;card.dataset.multiDownloadReady='1';const options=optionsFor(item);if(options.length<2)return;const actions=card.querySelector('.library-actions'),primary=actions?.querySelector('.primary-action');if(!actions||!primary)return;const button=document.createElement('button');button.type='button';button.className='primary-action mod-download-toggle';button.setAttribute('aria-expanded','false');button.innerHTML=`${icon('download-modern')}<span>Download</span>${icon('chevron-down')}`;primary.replaceWith(button);const panel=document.createElement('div');panel.className='mod-download-options-panel';panel.hidden=true;panel.innerHTML=options.map((file,index)=>`<a class="collection-row mod-download-option" data-mod-id="${safe(item.id)}" href="${safe(file.url)}" target="_blank" rel="noopener noreferrer"><span class="collection-index">${String(index+1).padStart(2,'0')}</span><span class="collection-copy"><strong>${safe(file.label)}</strong><small>${index===0?'Primary file':'Download file'}</small></span><span class="collection-action">${icon('download-modern')}</span></a>`).join('');actions.after(panel);button.addEventListener('click',()=>{const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));panel.hidden=open;card.classList.toggle('has-download-options-open',!open)})}
async function init(){if(document.body?.dataset.page!=='downloads')return;await waitForLibrary();const mods=await getMods(),byId=new Map(mods.map(x=>[String(x.id),x]));document.querySelectorAll('.library-card[data-id]').forEach(card=>{const item=byId.get(card.dataset.id);if(item)enhance(card,item)});const feed=document.querySelector('.library-feed');if(feed)new MutationObserver(()=>feed.querySelectorAll('.library-card[data-id]').forEach(card=>{const item=byId.get(card.dataset.id);if(item)enhance(card,item)})).observe(feed,{childList:true,subtree:true})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
